-- SECTION: INVITE CODES (Care Circle Onboarding)
-- ============================================================

-- Short-lived invite codes generated by caregivers to add family members.
-- Preferred onboarding flow: Code → QR → Phone Search.
CREATE TABLE IF NOT EXISTS invite_codes (
  id                UUID              PRIMARY KEY DEFAULT gen_random_uuid(),
  code              VARCHAR(10)       NOT NULL UNIQUE,
  patient_id        UUID              NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_by        UUID              NOT NULL REFERENCES users(id),
  relationship_type relationship_type NOT NULL DEFAULT 'FAMILY_CLOSE',
  expires_at        TIMESTAMPTZ       NOT NULL,
  used_at           TIMESTAMPTZ,
  used_by           UUID              REFERENCES users(id),
  created_at        TIMESTAMPTZ       NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_invite_codes_code    ON invite_codes (code) WHERE used_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_invite_codes_patient ON invite_codes (patient_id);


-- SECTION: CARE NOTES
-- ============================================================

-- Informational notes posted by family members for the care team.
-- Examples: "Patient becomes anxious after sunset"
-- Visible to caregivers; read-only for family after posting.
CREATE TABLE IF NOT EXISTS care_notes (
  id          UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
  patient_id  UUID         NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  author_id   UUID         NOT NULL REFERENCES users(id),
  content     TEXT         NOT NULL,
  is_pinned   BOOLEAN      NOT NULL DEFAULT FALSE,
  created_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_care_notes_patient ON care_notes (patient_id, created_at DESC);


